
import fs from 'fs';
import { v4 as uuidv4 } from 'uuid';

const invalidUsers = JSON.parse(fs.readFileSync('invalid_users.json', 'utf8'));

let migrationSQL = `-- Users Table UUID Migration V2 (Policy Safe)
-- Generated by Antigravity Agent
-- Date: ${new Date().toISOString()}

BEGIN;

-- 1. Drop Blocking Policies
DROP POLICY IF EXISTS "Enable update for creators and admins" ON public.school_outreach_reports;
-- Also drop others that might rely on users.id casting
DROP POLICY IF EXISTS "Enable read access for all authenticated users" ON public.school_outreach_reports;
DROP POLICY IF EXISTS "Enable insert for authenticated users" ON public.school_outreach_reports;

-- 2. Data Correction (Fix 4 Invalid Rows)
`;

let rollbackSQL = `-- Users Table UUID Rollback V2
-- Generated by Antigravity Agent

BEGIN;

-- 1. Revert Type (UUID -> TEXT)
ALTER TABLE users ALTER COLUMN id TYPE text;

-- 2. Drop Default
ALTER TABLE users ALTER COLUMN id DROP DEFAULT;

-- 3. Restore Legacy IDs
`;

// ... (Reuse the same ID mapping logic)
invalidUsers.forEach(u => {
    // We hardcode the mapping to match V1 if possible, or just generate new ones.
    // For consistency, let's use the SAME UUIDs as V1 if we can, but since I can't read V1 in this context easily:
    const newUUID = uuidv4();
    migrationSQL += `UPDATE users SET id = '${newUUID}' WHERE id = '${u.id}'; -- Was: ${u.username}\n`;
    rollbackSQL += `UPDATE users SET id = '${u.id}' WHERE id = '${newUUID}'; -- Restore ${u.username}\n`;
});

migrationSQL += `
-- 3. Schema Hardening
ALTER TABLE users ALTER COLUMN id SET DEFAULT gen_random_uuid();

-- 4. Type Conversion
ALTER TABLE users ALTER COLUMN id TYPE uuid USING id::uuid;

-- 5. Restore Policies (Updated for UUID)
-- "Enable update for creators and admins"
-- Old: WHERE users.id = auth.uid()::text AND ...
-- New: WHERE users.id = auth.uid() AND ... (auth.uid() returns uuid)

CREATE POLICY "Enable update for creators and admins" ON public.school_outreach_reports
    FOR UPDATE USING (
        -- submitted_by is still TEXT?? If so, we need to cast auth.uid() to text for that comparison.
        -- users.id is now UUID.
        (auth.uid()::text = submitted_by) OR 
        EXISTS (
            SELECT 1 FROM public.users 
            WHERE users.id = auth.uid() -- No cast needed for UUID=UUID
            AND (users.role IN ('Super Admin', 'Administrator', 'Head of Dept'))
        )
    );

-- Restore others as-is (they check auth.role(), not users table)
CREATE POLICY "Enable read access for all authenticated users" ON public.school_outreach_reports
    FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "Enable insert for authenticated users" ON public.school_outreach_reports
    FOR INSERT WITH CHECK (auth.role() = 'authenticated');

COMMIT;
`;

rollbackSQL += `
-- 4. Restore Original Policies
CREATE POLICY "Enable update for creators and admins" ON public.school_outreach_reports
    FOR UPDATE USING (
        auth.uid()::text = submitted_by OR 
        EXISTS (
            SELECT 1 FROM public.users 
            WHERE users.id = auth.uid()::text 
            AND (users.role IN ('Super Admin', 'Administrator', 'Head of Dept'))
        )
    );
    
CREATE POLICY "Enable read access for all authenticated users" ON public.school_outreach_reports
    FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "Enable insert for authenticated users" ON public.school_outreach_reports
    FOR INSERT WITH CHECK (auth.role() = 'authenticated');

COMMIT;
`;

fs.writeFileSync('d:/Manifest System/backend/database/users_uuid_migration_v2.sql', migrationSQL);
fs.writeFileSync('d:/Manifest System/backend/database/users_uuid_rollback_v2.sql', rollbackSQL);

console.log("Generated V2 migration and rollback scripts.");
